{
  "title": "Tính bán kính mặt cầu ngoại tiếp tứ diện OABC",
  "description": "Dựng tứ diện OABC với OA, OB, OC đôi một vuông góc và có độ dài bằng 2. Tìm tâm mặt cầu ngoại tiếp và tính bán kính của nó.",
  "memory_declarations": [
    {
      "name": "OABC",
      "type": "solid"
    },
    {
      "name": "R",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "label": "Gốc tọa độ O"
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [2, 0, 0],
      "source_fact_id": "oa_length",
      "model_assumption": "oa_ob_oc_perpendicular",
      "label": "Điểm A trên trục Ox"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [0, 2, 0],
      "source_fact_id": "ob_length",
      "model_assumption": "oa_ob_oc_perpendicular",
      "label": "Điểm B trên trục Oy"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 0, 2],
      "source_fact_id": "oc_length",
      "model_assumption": "oa_ob_oc_perpendicular",
      "label": "Điểm C trên trục Oz"
    },
    {
      "kind": "assign",
      "target_var": "vec_OB",
      "expr": {
        "kind": "vector_from_points",
        "from_point": "O",
        "to_point": "B"
      },
      "label": "Vectơ OB"
    },
    {
      "kind": "assign",
      "target_var": "vec_OC",
      "expr": {
        "kind": "vector_from_points",
        "from_point": "O",
        "to_point": "C"
      },
      "label": "Vectơ OC"
    },
    {
      "kind": "construct_point",
      "target_var": "A_prime",
      "expr": {
        "kind": "translate",
        "point": "A",
        "vector": "vec_OB"
      },
      "label": "Điểm A' (2,2,0) = A + OB"
    },
    {
      "kind": "construct_point",
      "target_var": "D",
      "expr": {
        "kind": "translate",
        "point": "A_prime",
        "vector": "vec_OC"
      },
      "label": "Điểm D (2,2,2) = A' + OC, đỉnh đối diện O của hình hộp"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "O",
        "b": "D"
      },
      "label": "Tâm M của mặt cầu ngoại tiếp (trung điểm OD)"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "circumsphere",
      "curved_kind": "ball",
      "anchor": "M",
      "rim_point": "O",
      "label": "Mặt cầu ngoại tiếp tứ diện OABC"
    },
    {
      "kind": "construct_polygon",
      "target_var": "face_OAB",
      "vertices": ["O", "A", "B"],
      "label": "Mặt OAB"
    },
    {
      "kind": "construct_polygon",
      "target_var": "face_OAC",
      "vertices": ["O", "A", "C"],
      "label": "Mặt OAC"
    },
    {
      "kind": "construct_polygon",
      "target_var": "face_OBC",
      "vertices": ["O", "B", "C"],
      "label": "Mặt OBC"
    },
    {
      "kind": "construct_polygon",
      "target_var": "face_ABC",
      "vertices": ["A", "B", "C"],
      "label": "Mặt ABC"
    },
    {
      "kind": "construct_solid",
      "target_var": "OABC",
      "vertices": ["O", "A", "B", "C"],
      "faces": [
        ["O", "A", "B"],
        ["O", "A", "C"],
        ["O", "B", "C"],
        ["A", "B", "C"]
      ],
      "label": "Tứ diện OABC"
    },
    {
      "kind": "assign",
      "target_var": "R",
      "expr": {
        "kind": "measure",
        "quantity": "radius",
        "of": "circumsphere"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách xác định tâm và bán kính mặt cầu ngoại tiếp một tứ diện đặc biệt có ba cạnh đôi một vuông góc tại một đỉnh, bằng cách sử dụng hệ tọa độ Descartes và các phép dựng hình học cơ bản như tịnh tiến và tìm trung điểm."
}

